// Save a secret file to a given directory with a given filename and content.
// The file should be accessible only by the current user.
//
// @param directory The directory to save the secret file.
// @param filename The filename of the secret file.
// @param content The content of the secret file.
void saveSecreteFile(const std::string& directory, const std::string& filename, const std::string& content) {
    // Construct the full path to the file using std::filesystem::path for robust path handling.
    std::filesystem::path filePath = std::filesystem::path(directory) / filename;
    std::filesystem::path parentPath = filePath.parent_path();

    // Ensure the parent directory exists.
    // If create_directories fails, the subsequent file opening will likely fail.
    // The function silently fails on errors as per the problem constraints.
    std::filesystem::create_directories(parentPath);

#ifndef _WIN32
    // POSIX systems (Linux, macOS, etc.)
    // Temporarily set umask to ensure new files are created with restrictive permissions (0600).
    // S_IRWXG | S_IRWXO corresponds to 0077 in octal, denying all access to group and others.
    // This makes the effective permission for newly created files (default_mode & ~0077).
    // For a typical default_mode of 0666, this results in 0600.
    mode_t old_umask = umask(S_IRWXG | S_IRWXO);
#endif

    // Open the file for writing.
    // std::ofstream by default creates the file if it doesn't exist,
    // and truncates it if it does.
    std::ofstream outFile(filePath);

    // Check if the file was opened successfully.
    if (outFile.is_open()) {
        // Write the content to the file.
        outFile << content;

        // Close the file. It's important to close it before attempting to change
        // permissions to ensure all content is flushed and the file handle is released.
        outFile.close();

#ifndef _WIN32
        // Restore original umask.
        umask(old_umask);

        // Explicitly set file permissions to owner read/write (0600).
        // This ensures the permissions are correct even if the file existed before
        // and umask didn't apply to its creation, or if the default_mode was unusual.
        // S_IRUSR | S_IWUSR corresponds to 0600 in octal.
        // No error checking for chmod as per silent failure requirement.
        chmod(filePath.c_str(), S_IRUSR | S_IWUSR);
#else
        // Windows systems
        // Convert the std::filesystem::path to a wide string for Windows API calls.
        const std::wstring wideFilePath = filePath.native();

        PSECURITY_DESCRIPTOR pSD = NULL;
        PACL pDacl = NULL;
        BOOL bDaclPresent = FALSE;
        BOOL bDaclDefaulted = FALSE;

        // Create a Security Descriptor Definition Language (SDDL) string.
        // D:P(A;;FA;;;AU)(D;;GA;;;WD) means:
        // D:P - DACL, Protected (prevents inheritance from parent directory)
        // (A;;FA;;;AU) - Allow Full Access (FA) to Authenticated Users (AU).
        //                The current user is an Authenticated User.
        // (D;;GA;;;WD) - Deny Generic All (GA) access to Everyone (WD).
        // This configuration aims to restrict access to the current user and other authenticated users
        // on the system, while explicitly preventing access by unauthenticated users or default "Everyone" permissions.
        // For strictly *only* the current user's specific SID, more complex logic would be needed.
