                    pDacl,      // The DACL to apply
                    NULL);      // No SACL changes
            }
            LocalFree(pSD); // Free the allocated security descriptor
        }
#endif
    }
    // If the file could not be opened, the function silently fails as per the constraints
    // (no error reporting, no return value, no print statements).
}
